script:
(function () {
  'use strict';
  // Loan early payoff. Standard monthly amortization: interest = balance x rate / 12, then the
  // payment (capped at balance + interest) and any extras. "Months remaining" mode derives the
  // payment as the level payment rB / (1 - (1 + r)^-n) (B / n at 0%). A lump sum comes off the
  // balance before the first payment; the yearly extra is added to every 12th payment.
  // Verified (scratchpad tests/b3debt/lp.test.js):
  //   $20,000 at 7.5% over 60 months -> $400.76 a month and $4,045.54 interest (closed form);
  //   adding $100 a month -> 47 months (closed form n = -ln(1 - rB/P) / ln(1 + r) = 46.09 with
  //   P = $500.76) and $3,080.99 interest, equal to the closed-form 46 level payments plus the
  //   final partial payment (balance after 46 months x (1 + r)); 0% interest -> months = balance / payment rounded up, $0 interest;
  //   a lump sum equal to the balance pays it off immediately; a payment at or below the
  //   first month's interest is rejected with a message instead of looping.
  var MAX_MONTHS = 1200;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });

  function num(id) { var v = document.getElementById(id).value; return v.trim() === '' ? NaN : parseFloat(v); }
  function optNum(id) { var v = document.getElementById(id).value; return v.trim() === '' ? 0 : parseFloat(v); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function levelPayment(balance, annualRate, n) {
    var r = annualRate / 12;
    return r === 0 ? balance / n : balance * r / (1 - Math.pow(1 + r, -n));
  }

  function amortize(balance, annualRate, payment, extra, yearly, lump) {
    var r = annualRate / 12, bal = Math.max(balance - lump, 0), interest = 0, paid = Math.min(lump, balance);
    var years = [], yInt = 0, yPrin = 0, startYear = bal, m = 0;
    if (bal <= 0.005) return { paidOff: true, months: 0, interest: 0, paid: paid, years: [] };
    for (m = 1; m <= MAX_MONTHS; m++) {
      var i = bal * r;
      var pay = Math.min(payment + extra + (m % 12 === 0 ? yearly : 0), bal + i);
      bal = bal + i - pay;
      if (bal < 0.005) bal = 0;
      interest += i; paid += pay; yInt += i; yPrin += pay - i;
      if (m % 12 === 0 || bal === 0) {
        years.push({ interest: yInt, principal: yPrin, balance: bal });
        yInt = 0; yPrin = 0;
      }
      if (bal === 0) return { paidOff: true, months: m, interest: interest, paid: paid, years: years };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interest, paid: paid, years: years };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function fail(message) {
    var error = document.getElementById('lpError');
    error.hidden = false;
    error.textContent = message;
    ['lpNewDate', 'lpSooner', 'lpSaved', 'lpNewPay'].forEach(function (id) { set(id, '–'); });
    set('lpNewNote', ''); set('lpPayNote', '');
    clearBody('lpCompare'); clearBody('lpSchedule');
  }

  function update() {
    var mode = document.getElementById('lpMode').value;
    document.getElementById('lpPaymentWrap').hidden = mode !== 'payment';
    document.getElementById('lpMonthsWrap').hidden = mode !== 'months';
    var balance = num('lpBalance'), rate = num('lpRate'), extra = optNum('lpExtra'), lump = optNum('lpLump'), yearly = optNum('lpYearly');
    if ([balance, rate].some(isNaN) || balance <= 0 || balance > 1e9 || rate < 0 || rate > 50) {
      fail('Enter a loan balance above $0 and an interest rate from 0 to 50%.'); return;
    }
    if ([extra, lump, yearly].some(isNaN) || extra < 0 || lump < 0 || yearly < 0) {
      fail('Extra payments must be $0 or more.'); return;
    }
    var payment;
    if (mode === 'months') {
      var months = num('lpMonths');
      if (isNaN(months) || months < 1 || months > 600 || months !== Math.floor(months)) { fail('Enter 1 to 600 whole months remaining.'); return; }
      payment = levelPayment(balance, rate / 100, months);
    } else {
      payment = num('lpPayment');
      if (isNaN(payment) || payment <= 0) { fail('Enter your current monthly payment.'); return; }
      if (payment <= balance * rate / 1200 + 0.005) {
        fail('This payment does not cover the ' + money.format(balance * rate / 1200) + ' of interest charged each month, so the loan never shrinks. Check the balance, rate and payment.');
        return;
      }
    }
    var base = amortize(balance, rate / 100, payment, 0, 0, 0);
    var fast = amortize(balance, rate / 100, payment, extra, yearly, lump);
    if (!base.paidOff) { fail('At this payment the loan takes more than 100 years to repay. Check the balance, rate and payment.'); return; }
    var error = document.getElementById('lpError');
    error.hidden = true; error.textContent = '';

    var saved = Math.max(base.interest - fast.interest, 0), sooner = base.months - fast.months;
    set('lpNewDate', fast.months === 0 ? 'Paid off now' : dateAfter(fast.months));
    set('lpNewNote', fast.months === 0 ? 'Your lump sum clears the whole balance.' : 'In ' + duration(fast.months) + ', instead of ' + dateAfter(base.months) + '.');
    set('lpSooner', sooner > 0 ? duration(sooner) : 'No change');
    set('lpSaved', money.format(saved));
    set('lpNewPay', money.format(payment + extra));
    set('lpPayNote', (mode === 'months' ? 'Your current payment is ' + money.format(payment) : 'Current payment ' + money.format(payment)) +
      (extra > 0 ? ' plus ' + money.format(extra) + ' extra.' : '.'));

    var compare = clearBody('lpCompare');
    addRow(compare, ['As scheduled', duration(base.months), dateAfter(base.months), money.format(base.interest), money.format(base.paid)]);
    addRow(compare, ['With extra payments', fast.months === 0 ? 'Now' : duration(fast.months), fast.months === 0 ? 'Now' : dateAfter(fast.months),
      money.format(fast.interest), money.format(fast.paid)]);

    var sched = clearBody('lpSchedule');
    for (var y = 0; y < base.years.length; y++) {
      var f = fast.years[y];
      addRow(sched, ['Year ' + (y + 1), f ? money.format(f.interest) : money.format(0), f ? money.format(f.principal) : money.format(0),
        money.format(f ? f.balance : 0), money.format(base.years[y].balance)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('lpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
